  effect:addMod(xi.mod.FOOD_EVAP, 11)\n    --  effect:addMod(xi.mod.FOOD_EVA_CAP, 55)\n    --  effect:addMod(xi.mod.FOOD_MEVAP, 11)\n    --  effect:addMod(xi.mod.FOOD_MEVA_CAP, 55)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_red_curry.lua"]={["Path"]="scripts/items/serving_of_red_curry.lua",["SHA256"]="033f1dd4b692dec8080ddc5b212e2e1532f3bd47be6ae6db6e0c58a22b8aa5bd",["Text"]="-----------------------------------\n-- ID: 4298\n-- Item: serving_of_red_curry\n-- Food Effect: 3 hours, All Races\n-- Group Effects -- https://wiki.ffo.jp/html/4903.html\n-----------------------------------\n-- HP +25\n-- Strength +7\n-- Agility +1\n-- Intelligence -2\n-- HP recovered while healing +2\n-- MP recovered while healing +1\n-- Attack +23% (Cap: 150@652 Base Attack)\n-- Ranged Attack +23% (Cap: 150@652 Base Ranged Attack)\n-- Demon Killer +4\n-- Resist Sleep +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.FOOD_HP,        35,  25 },\n    [ 2] = { xi.mod.STR,             7,   7 },\n    [ 3] = { xi.mod.AGI,             3,   1 },\n    [ 4] = { xi.mod.INT,             0,  -2 },\n    [ 5] = { xi.mod.HPHEAL,          6,   2 },\n    [ 6] = { xi.mod.MPHEAL,          3,   1 },\n    [ 7] = { xi.mod.FOOD_ATTP,      25,  23 },\n    [ 8] = { xi.mod.FOOD_ATT_CAP,  150, 150 },\n    [ 9] = { xi.mod.FOOD_RATTP,     25,  23 },\n    [10] = { xi.mod.FOOD_RATT_CAP, 150, 150 },\n    [11] = { xi.mod.DEMON_KILLER,    4,   4 },\n    [12] = { xi.mod.SLEEPRES,        3,   3 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 3\n        if partySize >= 4 then\n            column = 2\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_royal_jelly.lua"]={["Path"]="scripts/items/serving_of_royal_jelly.lua",["SHA256"]="2e925c73f9a6684d520b2a3b5797805c3c6b12c1a768e8bc5be1e18beb379223",["Text"]="-----------------------------------\n-- ID: 4508\n-- Item: Serving of Royal Jelly\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- MP Recovery while healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_salmon_eggs.lua"]={["Path"]="scripts/items/serving_of_salmon_eggs.lua",["SHA256"]="52460fabb2fbb74512da5974fb86b4fca355bde88e57a5ca2e79361c566d4e39",["Text"]="-----------------------------------\n-- ID: 5217\n-- Item: serving_of_salmon_eggs\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 6\n-- Magic 6\n-- Dexterity 2\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = fun