fect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 100)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_snowy_rolanberry.lua"]={["Path"]="scripts/items/serving_of_snowy_rolanberry.lua",["SHA256"]="c5c5259c82ef4fc7db2955a8c0c3b50d5d228fbfe5da3b0650bc28def7304ea6",["Text"]="-----------------------------------\n-- ID: 4594\n-- Item: serving_of_snowy_rolanberry\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Magic % 19\n-- Magic Cap 60\n-- Intelligence 2\n-- Wind Res 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 19)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 60)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.WIND_MEVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_squirrels_delight.lua"]={["Path"]="scripts/items/serving_of_squirrels_delight.lua",["SHA256"]="4768ba5763250074a92918125a8942cc00e19cd54b6820cf08d089c04f04c6e5",["Text"]="-----------------------------------\n-- ID: 5554\n-- Item: serving_of_squirrels_delight\n-- Food Effect: 4Hrs, All Races\n-----------------------------------\n-- MP % 13 (cap 95)\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 13)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 95)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_vermillion_jelly.lua"]={["Path"]="scripts/items/serving_of_vermillion_jelly.lua",["SHA256"]="5b674b12e6d93a906db977c66c76c966e9a3cd1d0d566c97c56d62abe860128c",["Text"]="-----------------------------------\n-- ID: 5158\n-- Item: Vermillion Jelly\n-- Food Effect: 4 hours, All Races\n-----------------------------------\n-- MP +12%(Cap: 90@750 Base MP)\n-- Intelligence +6\n-- MP Recovered While Healing +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 12)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 90)\n    effect:addMod(xi.mod.INT, 6)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_yellow_curry.lua"]={["Path"]="scripts/items/serving_of_yellow_curry.lua",["SHA256"]="cc83bc656ad787f44bb3f15fc2729cb7b79eec44b1180d51034089d4fb4320a1",["Text"]="-----------------------------------\n-- ID: 4517\n-- Item: serving_of_yellow_curry\n-- Food Effect: 3hours, All Races\n-- https://wiki.ffo.jp/html/5679.html\n-----------------------------------\n-- Health Points 20\n-- Strength 5\n-- Agility 2\n-- Intelligence -4\n-- HP Recovered While Healing 2\n-- MP Recovered While Healing 1\n-- Attack 21% (caps @ 75)\n-- Ranged Attack 21% (caps @ 75)\n-- Resist Sleep +3\n-- Resist Stun +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.FOOD_HP,       30, 25, 20 },\n    [ 2] = { xi.mod.VIT,            2,  1,  0 },\n    [ 3] = { xi.mod.AGI,            3,  3,  2 },\n    [ 4] = { xi.mod.INT,           -2, -3, -4 },\n    [ 5] = { xi.mod.HPHEAL,         6,  4,  2 },\n    [ 6] = { xi.mod.MPHEAL,         3,  2,  1 },\n    [ 7] = { xi.mod.FOOD_ATTP,     22, 21, 21 },\n    [ 8] = { xi.mod.FOOD_ATT_CAP,  85, 80, 75 },\n    [ 9] = { xi.mod.FOOD_RATTP,    22, 21, 21 },\n    [10] = { xi.mod.FOOD_RATT_CAP, 85, 80, 75 },\n    [11] = { xi.mod.SLEEPRES,       4,  3,  3 },\n    [12] = { xi.mod.STUNRES,        5,  4,  4 },\n    [13] = { xi.mod.STR,            5,  5,  5 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 4\n        if partySize >= 4 then\n            column = 2\n        elseif partySize >= 2 then\n            column = 3\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_zaru_soba.lua"]={["Path"]="scripts/items/serving_of_zaru_soba.lua",["SHA256"]="42881dc2d15990b4408bc957fc8d962b2b1e09dde8abb7f0d05b54df5f175b7a",["Text"]="-----------------------------------\n-- ID: 5727\n-- Item: serving_of_zaru_soba\n-- Food Effect: 30Min?, All Races\n-----------------------------------\n-- Agility 3\n-- HP % 12 (cap 180)\n-- Resist Sleep +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.FOOD_HPP, 12)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 180)\n    effect:addMod(xi.mod.SLEEPRES, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_zaru_soba_+1.lua"]={["Path"]="scripts/items/serving_of_zaru_soba_+1.lua",["SHA256"]="d5bbaf9aa35b68dafa78abca8a8fda89c3844346c1a798401480552ce1cd2e43",["Text"]="-----------------------------------\n-- ID: 5728\n-- Item: serving_of_zaru_soba_+1\n-- Food Effect: 60min, All Races\n-----------------------------------\n-- Agility 4\n-- HP % 12 (cap 185)\n-- Resist Sleep +10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.FOOD_HPP, 12)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 185)\n    effect:addMod(xi.mod.SLEEPRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sha_wujings_lance_+1.lua"]={["Path"]="scripts/items/sha_wujings_lance_+1.lua",["SHA256"]="0961bf463ee01adc9bdbe4b6713d850a7ef027b1583670b041962a528ae5ae1c",["Text"]="-----------------------------------\n--  ID: 21868\n--  Sha Wujing's lance +1\n--  When used, you will obtain a stack of Distilled Water\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_DISTILLED_WATER, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/shadow_lord_shirt.lua"]={["Path"]="scripts/items/shadow_lord_shirt.lua",["SHA256"]="d3a1a81da370061e3f4175bd185bb5f97c59299c2fa5a65a785893a046d70478",["Text"]="-----------------------------------\n-- ID: 26517\n-- Item: Shadow Lord Shirt\n-- Teleports user to Castle Zvahl Keep\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    -- Need retail verification: Is having set foot in the zone a requirement?\n    if not target:hasVisitedZone(xi.zone.CASTLE_ZVAHL_KEEP) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    -- May need a retail capture to verify actual position\n    -- https://ffxiclopedia.fandom.com/wiki/Shadow_Lord_Shirt states teleports next to HP#1\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.ZVAHL_KEEP, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/shadow_throne.lua"]={["Path"]="scripts/items/shadow_throne.lua",["SHA256"]="1cae1b6dd18348dd40c8fd07cf377b395b9febc92bc10bbab6a75e218212d53f",["Text"]="-----------------------------------\n-- ID: 6410\n-- Item: Shadow Throne\n-- Item Effect: Grant Leaf bench key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.SHADOW_THRONE\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, xi.item.SHADOW_THRONE, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/shall_shell.lua"]={["Path"]="scripts/items/shall_shell.lua",["SHA256"]="eb79fd6739c659e056238b8ad6ddd84ac45fb7dac8cc0a17d4cd1c6653f5a5d4",["Text"]="-----------------------------------\n-- ID: 4484\n-- Item: shall_shell\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-- Defense % 16.4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 16.4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/she-slime_hat.lua"]={["Path"]="scripts/items/she-slime_hat.lua",["SHA256"]="e01ce4d62430e24adfd7775456068c95c68c9164533bca12acb1536818556da0",["Text"]="-----------------------------------\n-- ID: 27726\n-- Item: She-Slime Hat\n-- Dispense: She-Slime Candy\n-- TODO: Add hidden set effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SHE_SLIME_CANDY, math.randomInt(5, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/sheep_cap_+1.lua"]={["Path"]="scripts/items/sheep_cap_+1.lua",["SHA256"]="c05ec6392b87109eb7e1d6f4f590dd42c7d3080dea155da5a198811e580c5a5a",["Text"]="-----------------------------------\n--  ID: 26720\n--  Sheep Cap +1\n--  When used, you will obtain one of eleven random items. They are:\n--  Faerie Apple, Sunflower Seeds, Red Moko Grass, La Theine Cabbage, Boyahda Moss,\n--  Pine Nuts, Beaugreens, Acorn, Dung, Batagreens, and Moko Grass\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    local giftList =\n    {\n        xi.item.FAERIE_APPLE,\n        xi.item.HANDFUL_OF_SUNFLOWER_SEEDS,\n        xi.item.CLUMP_OF_RED_MOKO_GRASS,\n        xi.item.LA_THEINE_CABBAGE,\n        xi.item.CLUMP_OF_BOYAHDA_MOSS,\n        xi.item.HANDFUL_OF_PINE_NUTS,\n        xi.item.CLUMP_OF_BEAUGREENS,\n        xi.item.ACORN,\n        xi.item.CLUMP_OF_BATAGREENS,\n        xi.item.CLUMP_OF_MOKO_GRASS\n    }\n\n    local gift = math.randomInt(1, #giftList)\n\n    npcUtil.giveItem(target, { { giftList[gift], 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/sheet_of_divine_tunes.lua"]={["Path"]="scripts/items/sheet_of_divine_tunes.lua",["SHA256"]="b8cb2d63be75ee8c785ca2c6114f63e876fd601064466513da9c720b95c42bdb",["Text"]="-----------------------------------\n-- ID: 6704\n-- Item: Divine Tunes\n-- Grants keyitem: SHEET_OF_DIVINE_TUNES\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    -- TODO: The error message returned by this is wrong\n    return target:hasKeyItem(xi.keyItem.SHEET_OF_DIVINE_TUNES) and 1 or 0\nend\n\nitemObject.onItemUse = function(target)\n    -- TODO: This actually produces the message: `->Obtained key item: {key item name}.`\n    -- TODO: We don't yet have this message type mapped out\n    npcUtil.giveKeyItem(target, xi.keyItem.SHEET_OF_DIVINE_TUNES)\nend\n\nreturn itemObject\n"},["scripts/items/sheet_of_near_east_tunes.lua"]={["Path"]="scripts/items/sheet_of_near_east_tunes.lua",["SHA256"]="d8f75e5da9f8be356f7aad5776322f299e3c32eb2e877078dadc7026e7d3ee99",["Text"]="-----------------------------------\n-- ID: 6696\n-- Item: Near East Tunes\n-- Grants keyitem: SHEET_OF_NEAR_EAST_TUNES\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    -- TODO: The error message returned by this is wrong\n    return target:hasKeyItem(xi.keyItem.SHEET_OF_NEAR_EAST_TUNES) and 1 or 0\nend\n\nitemObject.onItemUse = function(target)\n    -- TODO: This actually produces the message: `->Obtained key item: {key item name}.`\n    -- TODO: We don't yet have this message type mapped out\n    npcUtil.giveKeyItem(target, xi.keyItem.SHEET_OF_NEAR_EAST_TUNES)\nend\n\nreturn itemObject\n"},["scripts/items/shellbuster.lua"]={["Path"]="scripts/items/shellbuster.lua",["SHA256"]="bcd6c5ef5e5cb147b2f102fea2868701630024c46dfe4fe833cd2312e062a4f7",["Text"]="-----------------------------------\n-- ID: 17415\n-- Item: Shellbuster\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local family = target:isMob() and target:getFamily() or xi.mobFamily.UNCLASSIFIED\n\n    if family ~= xi.mobFamily.QUADAV then\n        return 0, 0, 0\n    end\n\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 10 + utils.clamp(math.floor(dStat * 0.0926), 0, 5), -- 10 + 0-5% over 54 dINT\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/shining_trout.lua"]={["Path"]="scripts/items/shining_trout.lua",["SHA256"]="9d313a9a854d2dd112cdd46a8d4553ccff80d011aa77a367a3581cd3ca941494",["Text"]="-----------------------------------\n-- ID: 5791\n-- Item: shining_trout\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/shisai_kaboku.lua"]={["Path"]="scripts/items/shisai_kaboku.lua",["SHA256"]="40c5ad9a64076e06401f655e290055329fddc5bd2cd8e42e5b09bbb3ba5f12a0",["Text"]="-----------------------------------\n-- ID: 5881\n-- Shisai Kaboku\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/shock_subligar.lua"]={["Path"]="scripts/items/shock_subligar.lua",["SHA256"]="6ba84799aed8e043e55bfcb6c4bb2213724d851de3615580de4081f50c46f063",["Text"]="-----------------------------------\n-- ID: 15650\n-- Item: shock subligar\n-- Item Effect: Shock Spikes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.SHOCK_SPIKES, { power = 7, duration = 180, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/shogun_rice_ball.lua"]={["Path"]="scripts/items/shogun_rice_ball.lua",["SHA256"]="223fddc6817311207fca2459a4531502a5ee9886f4c2fb096e0b8a5db01c6d8f",["Text"]="-----------------------------------\n-- ID: 4278\n-- Item: Shogun Rice Ball\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- HP +20\n-- Dex +4\n-- Vit +4\n-- Chr +4\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Atk +50\n-- Def +30\n-- Double Attack +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.CHR, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/shrimp_cracker.lua"]={["Path"]="scripts/items/shrimp_cracker.lua",["SHA256"]="c02440b46673ec9feb0fce7ba905603ff24a095969cf9f02cb4700af774fc5a3",["Text"]="-----------------------------------\n-- ID: 5635\n-- Item: shrimp_cracker\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Vitality 1\n-- DEF +10\n-- Amorph Killer 10\n-- Resist Virus +10\n-- HP Recovered While Healing 8\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.DEF, 10)\n    effect:addMod(xi.mod.AMORPH_KILLER, 10)\n    effect:addMod(xi.mod.VIRUSRES, 10)\n    effect:addMod(xi.mod.HPHEAL, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/shrimp_cracker_+1.lua"]={["Path"]="scripts/items/shrimp_cracker_+1.lua",["SHA256"]="27baf8d8d0680e56dd5c83f43946cf04d56ff9404876f43c6e03e6efa87c0c54",["Text"]="-----------------------------------\n-- ID: 5636\n-- Item: shrimp_cracker_+1\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Vitality 2\n-- Defense +10\n-- Amorph Killer 12\n-- Resist Virus 12\n-- HP Recovered While Healing 9\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.DEF, 10)\n    effect:addMod(xi.mod.AMORPH_KILLER, 12)\n    effect:addMod(xi.mod.VIRUSRES, 12)\n    effect:addMod(xi.mod.HPHEAL, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/shuriken_pouch.lua"]={["Path"]="scripts/items/shuriken_pouch.lua",["SHA256"]="20c831da8ef97e0a966a7e24c3239b69d7f5321857560a47dbd77c79c3a01f43",["Text"]="-----------------------------------\n-- ID: 6299\n-- Item: Sh. Pouch\n-- When used, you will obtain one stack of Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/silken_sash.lua"]={["Path"]="scripts/items/silken_sash.lua",["SHA256"]="4d3ff96f9e185ffc82a3799b75c26693fd44d2fd0e6d6d65cb59ea596422d6f8",["Text"]="-----------------------------------\n-- ID: 5632\n-- Item: Silken Sash\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP Recovered while healing +3\n-- MP Recovered while healing +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/silken_siesta.lua"]={["Path"]="scripts/items/silken_siesta.lua",["SHA256"]="0ef4688d7cfaf6d839da406834f42e5e4c6edbdd84c69b24fea832f8188fa027",["Text"]="-----------------------------------\