nEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/simit.lua"]={["Path"]="scripts/items/simit.lua",["SHA256"]="4ed3f2405835be3efccf6974b5bfb0b9e2e86bf67e7f2f45562f29b47be94fd6",["Text"]="-----------------------------------\n-- ID: 5596\n-- Item: simit\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 16\n-- Dexterity -1\n-- Vitality 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 16)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/simit_+1.lua"]={["Path"]="scripts/items/simit_+1.lua",["SHA256"]="e2a0a7ff8a6e76cc6e280844f2909058440f993edf736517d2df14200bb0df60",["Text"]="-----------------------------------\n-- ID: 5597\n-- Item: simit_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 18\n-- Vitality 4\n-- Defense 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 18)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.DEF, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sirocco_kukri.lua"]={["Path"]="scripts/items/sirocco_kukri.lua",["SHA256"]="7a2ae49d18abb86136a557e7ab074884381a905d662777107127df0e9edfe22d",["Text"]="-----------------------------------\n-- ID: 18018\n-- Item: Sirocco Kukri\n-- Additional effect: Wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 100,\n        basePower      = math.random(7, 10),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/sis_kebabi.lua"]={["Path"]="scripts/items/sis_kebabi.lua",["SHA256"]="d8d94577307014546e072df0aa46c97f5293b20d0799e09d0d184503d484337d",["Text"]="-----------------------------------\n-- ID: 5598\n-- Item: sis_kebabi\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 6\n-- Vitality -2\n-- Intelligence -2\n-- Attack % 20\n-- Attack Cap 70\n-- Ranged ATT % 20\n-- Ranged ATT Cap 70\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 70)\n    eff